package bo.com.ganadero.animales.infrastructure; import bo.com.ganadero.animales.domain.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class JdbcCategoriaAnimalRepository implements CategoriaAnimalRepository {private final JdbcClient jdbc;JdbcCategoriaAnimalRepository(JdbcClient j){jdbc=j;}public List<CategoriaAnimal> findActive(UUID e){return jdbc.sql("select * from ganado.categorias_animal where activo and (empresa_id is null or empresa_id=:e) order by edad_min_meses,nombre").param("e",e).query(this::map).list();}public Optional<CategoriaAnimal> findById(UUID id,UUID e){return jdbc.sql("select * from ganado.categorias_animal where id=:id and activo and (empresa_id is null or empresa_id=:e)").param("id",id).param("e",e).query(this::map).optional();}private CategoriaAnimal map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new CategoriaAnimal(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getString("codigo"),r.getString("nombre"),r.getString("sexo_aplicable"),(Integer)r.getObject("edad_min_meses"),(Integer)r.getObject("edad_max_meses"),r.getString("descripcion"),r.getBoolean("activo"));}}
